#!/usr/bin/env python3
"""Reduce final immutable survey evidence; never execute source applications."""
import argparse,collections,gzip,hashlib,json,os,pathlib,subprocess,sys
p=argparse.ArgumentParser();p.add_argument('--evidence',type=pathlib.Path,required=True);p.add_argument('--after-dir',type=pathlib.Path,required=True);p.add_argument('--code-commit',required=True);p.add_argument('--binary',type=pathlib.Path,required=True);a=p.parse_args()
tools=pathlib.Path(__file__).resolve().parent;report=tools.parent;data=report/'data';out=a.evidence/'ship-audits';out.mkdir(exist_ok=True)
before=a.evidence/'before-default/results.json';after=a.after_dir/'results.json';manual=a.evidence/'wave30-manual.json'
def run(*args,env=None):subprocess.run([sys.executable,*map(str,args)],check=True,env=env)
run(tools/'classify-older.py','--before',before,'--after',after,'--out',out)
run(tools/'reconcile-wave30.py','--manual',manual,'--after',after,'--out',out/'wave30-after-classifications.json')
run(tools/'calibration-retention.py',env={**os.environ,'SECP_AUDIT_DIR':str(a.evidence),'SECP_AFTER_DIR':str(a.after_dir)})
run(tools/'summarize.py','--before',before,'--after',after,'--older-before',out/'older-before-classifications.json','--older-after',out/'older-after-classifications.json','--wave30-manual',manual,'--wave30-after',out/'wave30-after-classifications.json','--out',report/'summary.json')
summary=json.loads((report/'summary.json').read_text());retention=json.loads((a.evidence/'calibration-retention.json').read_text())
assert all(summary['acceptance'].values());assert not any(n['classification']=='lost_question'for n in retention['findings'])
for name,path in {'after.json.gz':after,'after-measurement.json.gz':a.after_dir/'measurement.json','older-before-classifications.json.gz':out/'older-before-classifications.json','older-after-classifications.json.gz':out/'older-after-classifications.json','wave30-after-classifications.json.gz':out/'wave30-after-classifications.json','calibration-retention.json.gz':a.evidence/'calibration-retention.json','calibration-retention.md.gz':a.evidence/'calibration-retention.md'}.items():
 with gzip.open(data/name,'wb')as f:f.write(path.read_bytes())
def git(*args):return subprocess.check_output(['git',*args],text=True).strip()
roots=['snapback4/crates','snapback4/Cargo.toml','snapback4/Cargo.lock','snapback4/packages/snapback4/CHANGELOG.md']
inputs={r:git('rev-parse',f'{a.code_commit}:{r}')for r in roots}
qualification=dict(codeCommit=git('rev-parse',a.code_commit),codeInputs=inputs,codeInputDigest=hashlib.sha256(json.dumps(inputs,sort_keys=True).encode()).hexdigest(),binary=str(a.binary),binarySha256=hashlib.sha256(a.binary.read_bytes()).hexdigest(),version='0.4.43',profile='test, optimized; CARGO_INCREMENTAL=0 CARGO_PROFILE_DEV_DEBUG=0 CARGO_PROFILE_TEST_DEBUG=0',baselineBinarySha256='3e5b86eb9fdf84842c2fbf40ccb7019a64ec3ad02aef7e180801a1d4203fbffb',measurementDirectory=str(a.after_dir),sourceOnlyQualification=True,mac='skipped by brief')
(report/'qualification.json').write_text(json.dumps(qualification,indent=2)+'\n')
lines=['# SECP advisory precision evidence','',f"Qualified native: `{qualification['codeCommit'][:12]}`, version 0.4.43, SHA256 `{qualification['binarySha256']}`. No version bump, publication or push.",'','All 250 schemas of waves26–30 were checked in private disposable copies using the unchanged Integration27 survey runner. Original schemas, credentials and stores were never modified. All before/after source bundle hashes match. Both binaries report 0.4.43.','', '| Wave | False before | False after | Reduction | Median review decisions before → after | Default check p90 lines before → after |','|---|---:|---:|---:|---:|---:|']
for r in summary['waves']:
 lines.append(f"| {r['wave']} | {r['before']['false']} | {r['after'].get('false',0)} | {100*r['falseReduction']:.1f}% | {r['beforeMetrics']['reviewDecisions']['median']} → {r['afterMetrics']['reviewDecisions']['median']} | {r['beforeMetrics']['defaultCheckLines']['p90']} → {r['afterMetrics']['defaultCheckLines']['p90']} |")
old=summary['older'];w30=summary['wave30'];overall=summary['overall']
lines += ['',f"Wave30: **{w30['before']['false']} → {w30['after'].get('false',0)} false advisories**. Waves26–29: **{old['before']['false']} → {old['after'].get('false',0)}**, **{100*old['falseReduction']:.2f}% fewer**. Every selected final message names observed guards and the unproved case in one physical line.",'',f"Overall median review decisions: **{overall['before']['reviewDecisions']['median']} → {overall['after']['reviewDecisions']['median']}**. Decisions count current unacknowledged securityReviews, including gated questions, matching the expanded check --review campaign. Gate counts and default rendering are reported separately in summary.json.",'','False means the source already answers the emitted question; real_question is an open policy/filtering question, not an exploit verdict. Wave30 judgments were authored by an independent manual review of all 50 source bundles and 843 baseline/first-candidate note occurrences, then reconciled by unchanged source-backed diagnostic properties. Every new or mixed property is rejected for manual delta review. Older-wave labels use a source classifier plus 407 manually documented category/representative spot checks, covering every wave/code family; no unresolved fallback remains. Survival/disappearance is never classification evidence.','', 'The full per-occurrence evidence and source hashes are in data/*.json.gz; raw independent audit transcripts and all review rounds are retained. Remaining older-wave false notes are explicitly counted, not relabeled.','', '## Calibrated question retention','', 'All 54 non-dismissed Snapback findings (M/L) in waves26/28/30 were reviewed. Every one of the 31 findings with a relevant baseline question retains such a question; 23 lacked that question before. Partial question aspects (for example text versus upload, without proving mandatory presence) remain explicitly limited in the full evidence. This is question retention, not complete hole coverage or exploit qualification. Integration27 wave30 exact M-hole gate coverage remains **1/14**.','', '| Finding | Retained question(s) |','|---|---|']
def site(s):return f"{s['file']}:{s['line']}:{s.get('col',1)}"if isinstance(s,dict)else str(s)
for f in retention['findings']:
 if f['classification']=='retained':lines.append('| '+f['id']+' | '+', '.join(sorted({m['code']+' @ '+site(m['site'])for m in f['final_matches']}))+' |')
lines += ['', 'The JSON inventory lists all54 findings, including uncovered baselines, exact messages, source excerpts, hashes and narrow coverage aspects. No unrelated note in the same lane is counted as retention.','', '## Boundaries and verification','', 'LLP3000.036.004.001 is implemented. Final semantic reviews by Muse and fresh Codex both return READY; verbatim responses and rejected revisions are under llp/reviews. Source consistency is advisory relevance over authored constructors, never a database invariant or proof over seed/import/restore images. Gate/runtime/witness consumers do not consume these facts.','', 'The lane explicitly prohibits the full crate/client pools. tools/run-affected-scoped.sh invokes the required affected selector on the final commit, runs modified crates and applicable checks, and returns explicit exit95 for prohibited integration/legacy steps. Its receipt must not be reported as a fully green battery. WORKSTREAM-REPORT.md records the final actual results and any inherited legacy prerequisites. Mac is skipped.','', '## Reproduce','', 'Use ../integration27/tools/survey-final.py with immutable before/after binaries, --waves 26,27,28,29,30 --workers 8 --check-only --default-output. It copies top-level *.q and authored fixture JSONL to private temporary trees, with fresh campaign state. No acknowledgments or stores are copied. Both phases use the same runner.','', 'Run tools/classify-older.py --before <before/results.json> --after <after/results.json> --out <audit-dir>; tools/reconcile-wave30.py --manual <wave30-manual.json> --after <after/results.json> --out <audit-dir/wave30-after.json>; tools/calibration-retention.py accepts SECP_AUDIT_DIR and SECP_AFTER_DIR. tools/summarize.py validates complete label inventories and computes medians/p90s. Compressed inputs are supported by the classification/summary tools. The calibration reducer expects the canonical runner directory layout.','', 'Shared-host timings are recorded for provenance and are not isolated latency or publication claims. Source/code/binary digests bind this qualification; later evidence-only commits do not change its semantic inputs.']
(report/'README.md').write_text('\n'.join(lines)+'\n')
print('Final SECP evidence reduced; acceptance bars satisfied.')
